 */
const RK = { mode: 'd9', line: true };
export const rkStats = { asked: 0, staked: 0 };
/** While an asset's worth and the rez's price are worked out (both read the credit slide, whose need reads keep): the
 * inner keep stakes agendas only, as today (one level; without it the owner asks itself). */
let rkInside = false;
function assetStaked(state: GameState, v: GameState['corp']['servers'][string]): boolean {
  if (rkInside) return false;
  rkInside = true;
  try {
    return assetStakedIn(state, v);
  } finally {
    rkInside = false;
  }
}
function assetStakedIn(state: GameState, v: GameState['corp']['servers'][string]): boolean {
  const cards = v.root.filter(c => !isAgenda(c));
  if (!cards.length) return false;
  rkStats.asked++;
  const worths = cards.map(c => Math.max(0, corpCardValue(c, state, 'corp', true)));
  const worth = worths.reduce((a, b) => a + b, 0);
  if (!(worth > 0)) return false;
  if (RK.mode === 'upper') return (rkStats.staked++, true);
  const open = serverHold(state, v.id, { when: 'runnerTurn', corpCredits: 0 });
  const trash = Math.min(...cards.filter((_, i) => worths[i] > 0).map(c => (cardDef(c).trash_cost ?? Infinity)));
  if (!(open.budget - open.need >= trash)) return false;
  const hold = serverHold(state, v.id, { when: 'runnerTurn', corpCredits: Infinity });
  if (!hold.holds) return false;
  const price = sideCreditValue(state, 'corp', 'corp') - sideCreditValue({ ...state, corp: { ...state.corp, credits: state.corp.credits - hold.rezCost } }, 'corp', 'corp');
  if (!(worth > price)) return false;
  rkStats.staked++;
  return true;
}
